func makeAdder(n int) func(int) int {
    return func(x int) int {
        return x + n
    }
}

func main() {
    add5 := makeAdder(5)
    add10 := makeAdder(10)
    fmt.Println(add5(1), add10(1))
}

func countIf(nums []int, ok func(int) bool) int {
    total := 0
    for _, n := range nums {
        if ok(n) {
            total++
        }
    }
    return total
}

func main() {
    limit := 10
    nums := []int{4, 12, 7, 30}
    big := countIf(nums, func(n int) bool {
        return n > limit
    })
    fmt.Println(big)
}

